import {states,sources,feedback,total,downloads,freshness,matches,escapeHtml as e,safeUrl,validate} from './model.js';
const endpoint='/api/snapshot';
const $=id=>document.getElementById(id), num=x=>x==null?'—':new Intl.NumberFormat('zh-CN').format(x);
const date=(s,full=false)=>s?new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',...(full?{year:'numeric',hour:'2-digit',minute:'2-digit'}:{})}).format(new Date(s)):'尚无成功采集';
const link=(url,text,cls='')=>`<a class="${cls}" href="${e(safeUrl(url))}" target="_blank" rel="noopener noreferrer">${e(text)} ↗</a>`;
const empty=(title,text='')=>`<div class="empty"><strong>${e(title)}</strong>${e(text)}</div>`;
let data=null, transport='loading', requestBusy=false;
const selection=()=>({query:$('search').value,project:$('project').value});
function selected(){const {query,project}=selection();return data.projects.filter(p=>(project==='all'||p.id===project)&&matches([p.title,p.summary,p.repo],query))}
function releaseSelected(){const {query,project}=selection();return data.releases.filter(r=>(project==='all'||r.project===project)&&matches(r,query))}
function followSelected(){const {query,project}=selection();return data.followups.filter(r=>(project==='all'||r.project===project)&&matches(r,query))}
function status(){if(!data)return;const f=freshness(data);$('sync-status').className='sync-status'+(f.stale||f.failed.length||transport!=='remote'?' warning':'');let text=`数据采集于 ${date(data.generated_at,true)}（北京时间） · 计划每 15 分钟采集`;if(transport==='fallback')text='当前无法读取云端快照，正在展示随站发布的初始记录。'+text;else if(transport==='cache')text='云端读取失败，保留本地最后成功快照。'+text;else if(transport==='retained')text='刷新失败，保留上次快照。'+text;if(f.stale)text+=' · 已超过 45 分钟未更新';if(f.failed.length)text+=` · ${f.failed.length} 个来源异常，见数据说明`;$('sync-status').textContent=text}
function taskHtml(t,compact=false){const overdue=t.status!=='done'&&t.due<new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());return `<article class="task"><span class="task-icon">${t.status==='done'?'✓':'↗'}</span><div class="task-content"><h3>${link(t.source,t.title)}</h3>${compact?'':`<p>${e(t.note)}</p>`}<div class="task-meta">${e(t.project)}<br>${e(t.owner)} · ${e(t.due)}${overdue?' · 已逾期':''}</div></div><span class="task-status ${t.status==='done'?'done':''}">${e(states[t.status]||t.status)}</span></article>`}
function releaseHtml(r){const p=data.projects.find(p=>p.id===r.project);return `<article class="release-card"><div class="release-date">${e(r.date.slice(0,4))}<strong>${e(r.date.slice(5).replace('-',' / '))}</strong>版本 ${e(r.version)}</div><div class="release-body"><div class="release-top"><span class="badge">已发布</span><span>${e(p?.title||r.project)}</span></div><h3>${e(r.problem)}</h3><p>${e(r.new_explanation)}</p><details><summary>查看验收证据与后续计划</summary><p>${e(r.acceptance)}</p><p>下一步：${e(r.follow_up)}</p><p>${link(r.ci,'CI 验证')} · ${link(r.repo+'/blob/main/docs/RESEARCH.md','需求证据')}</p></details><div class="project-links">${link(r.release,'发行版本')}${(r.promotion||[]).filter(p=>p.status==='published_verified').map(p=>link(p.url,p.channel)).join('')}</div></div></article>`}
function renderChart(){const p=data.projects.find(p=>p.id===$('chart-project').value);const h=data.history.filter(h=>h.project===p?.id).sort((a,b)=>a.at.localeCompare(b.at));if(h.length<2){$('chart').innerHTML=`<div class="chart-empty"><b>${num(h[0]?.stars)} <span style="font-size:13px">Stars</span></b><span>观察从现在开始</span><span>已有 ${h.length} 次实测快照；有更多观测后再画趋势。</span></div>`;return}const lo=Date.parse(h[0].at),hi=Date.parse(h.at(-1).at),max=Math.max(1,...h.map(x=>x.stars)),min=0;const pts=h.map(x=>[32+(Date.parse(x.at)-lo)/(hi-lo||1)*480,140-(x.stars-min)/(max-min)*112]);const line=pts.map(p=>p.join(',')).join(' ');$('chart').innerHTML=`<div class="chart-wrap"><svg viewBox="0 0 550 176" role="img" aria-label="${e(p.title)} 星标趋势，${h.length} 次观测，当前 ${h.at(-1).stars} 星"><line x1="32" y1="28" x2="512" y2="28" stroke="#e5eae4" stroke-dasharray="3 4"/><line x1="32" y1="84" x2="512" y2="84" stroke="#e5eae4" stroke-dasharray="3 4"/><line x1="32" y1="140" x2="512" y2="140" stroke="#d9e1d7"/><text x="3" y="32">${max}</text><text x="3" y="144">0</text><polyline points="${line}" fill="none" stroke="#39805c" stroke-width="2.5"/><circle cx="${pts.at(-1)[0]}" cy="${pts.at(-1)[1]}" r="4" fill="#39805c"/><text x="32" y="167">${date(h[0].at,true)}</text><text x="512" y="167" text-anchor="end">${date(h.at(-1).at,true)}</text></svg></div>`}
function render(){if(!data)return;status();const ps=selected(),rs=releaseSelected().filter(r=>r.status==='published').sort((a,b)=>b.date.localeCompare(a.date)),ts=followSelected();const {project,query}=selection();const fs=data.projects.filter(p=>project==='all'||p.id===project).flatMap(feedback).filter(f=>matches(f,query));const pending=fs.filter(f=>f.state==='needs_reply').length,openTasks=ts.filter(t=>t.status!=='done').length;const incomplete=ps.some(p=>!p.issues?.ok||p.promotions.some(s=>!s.ok));const cards=[['维护项目',ps.length,'已登记的交付项目','◫'],['软件发布',rs.length,'经验证的实际发布记录','↗'],['GitHub Stars',total(ps,'stargazers_count'),'关注信号，不代表真实使用','☆'],['待处理',pending+openTasks,`${pending} 条待回复 · ${openTasks} 项跟进${incomplete?' · 部分来源异常':''}`,'↳']];$('metrics').innerHTML=cards.map(([label,value,note,icon])=>`<div class="metric"><div class="metric-label">${label}<span class="metric-icon">${icon}</span></div><div class="metric-value">${num(value)}</div><div class="metric-note">${note}</div></div>`).join('');$('next-actions').innerHTML=ts.filter(t=>t.status!=='done').slice(0,3).map(t=>taskHtml(t,true)).join('')||empty('当前没有待跟进事项','新增反馈会显示在反馈页。');$('project-count').textContent=`${ps.length} 个项目`;$('projects').innerHTML=ps.map(p=>`<article class="project-card"><div><div class="project-header"><h3>${e(p.title)}</h3><span class="badge">${e(p.stage)}</span></div><p>${e(p.summary)}</p><div class="project-links">${link('https://github.com/'+p.repo,'查看仓库')}${link('https://github.com/'+p.repo+'/issues','Issues')}<a href="#feedback">反馈与跟进 ↗</a></div>${sources(p).some(s=>!s.ok)?'<p class="error-label">部分来源采集失败；保留上次成功数值。</p>':''}</div><div class="project-stats"><div><b>${num(p.metrics.value?.stargazers_count)}</b><span>Stars</span></div><div><b>${num(p.metrics.value?.forks_count)}</b><span>Forks</span></div><div><b>${num(downloads(p))}</b><span>资产下载 · 含自测</span></div><div class="adoption">外部采用：${p.adoption==null?'未确认':e(p.adoption)} · ${e(p.adoption_note)}</div></div></article>`).join('')||empty('没有匹配的项目','试试清空搜索或切换项目。');$('latest-release').innerHTML=rs.slice(0,1).map(releaseHtml).join('')||empty('没有匹配的发布记录');$('releases').innerHTML=rs.map(releaseHtml).join('')||empty('没有匹配的发布记录');$('release-count').textContent=`${rs.length} 次交付`;$('followups').innerHTML=ts.length?`<div class="followup-list">${ts.map(t=>taskHtml(t)).join('')}</div>`:empty('当前没有匹配的跟进事项');const filter=$('feedback-filter').value;const visible=fs.filter(f=>filter==='all'||f.state===filter).sort((a,b)=>b.updated_at.localeCompare(a.updated_at));$('feedback').innerHTML=visible.map(f=>`<article class="feedback-card"><div><h3>${link(f.url,f.title)}</h3><p>${e(f.project)} · ${e(f.kind==='issue'?'Issue':'讨论评论')} · @${e(f.author||'已删除用户')}</p><p>${e(date(f.updated_at,true))} · ${num(f.comments)} 条回复</p></div><span><span class="task-status ${f.state==='replied'?'done':''}">${e(states[f.state])}</span></span></article>`).join('')||empty('还没有匹配的反馈',incomplete?'部分来源采集失败，请查看数据说明。':'已采集来源中暂无此类反馈。没有消息，也如实记录。');$('promotions').innerHTML=data.projects.filter(p=>project==='all'||p.id===project).flatMap(p=>p.promotions.map(s=>({...s,project:p.id}))).filter(s=>matches(s,query)).map(s=>s.value?`<article class="promotion"><span class="eyebrow">${e(s.value.channel)}</span><h3>${link(s.value.url,s.value.title)}</h3><p>${e(s.project)} · 已核验发布 · ${e(date(s.observed_at,true))} 采集${!s.ok?' · 来源异常，显示旧快照':''}</p><div class="numbers"><span><b>${num(s.value.upvotes)}</b>点赞 · 可能含作者</span><span><b>${num(s.value.comment_count)}</b>评论与回复</span></div></article>`:`<div class="empty">${e(s.key)} 采集失败，暂无成功数据</div>`).join('')||empty('暂无匹配的推广记录');$('nav-releases').textContent=data.releases.filter(r=>r.status==='published').length;$('nav-feedback').textContent=data.projects.flatMap(feedback).filter(f=>f.state==='needs_reply').length+data.followups.filter(t=>t.status!=='done').length;$('source-details').innerHTML=data.projects.flatMap(p=>sources(p).map(s=>`<div class="source-row"><strong>${e(p.title)} · ${e(s.name)}</strong><span>${s.ok?'采集成功':'采集失败'} · 最后成功：${e(date(s.observed_at,true))}</span>${s.error?`<span class="error-label">${e(s.error)}</span>`:''}</div>`)).join('');renderChart()}
function install(next){validate(next);if(data?.generated_at===next.generated_at){data=next;status();return}data=next;const old=$('project').value,chart=$('chart-project').value;$('project').innerHTML='<option value="all">全部项目</option>'+data.projects.map(p=>`<option value="${e(p.id)}">${e(p.title)}</option>`).join('');$('chart-project').innerHTML=data.projects.map(p=>`<option value="${e(p.id)}">${e(p.title)}</option>`).join('');$('project').value=data.projects.some(p=>p.id===old)?old:'all';if(data.projects.some(p=>p.id===chart))$('chart-project').value=chart;render()}
async function fetchJSON(url){const r=await fetch(url,{cache:'no-store',signal:AbortSignal.timeout(15000)});if(!r.ok)throw Error('HTTP '+r.status);return validate(await r.json())}
async function refresh(){if(requestBusy)return;requestBusy=true;$('refresh').disabled=true;try{const next=await fetchJSON(endpoint+'?t='+Math.floor(Date.now()/60000));transport='remote';install(next);try{localStorage.setItem('observatory-last-good',JSON.stringify(next))}catch{}}catch{if(data){transport='retained';status()}else{let cached=null;try{cached=validate(JSON.parse(localStorage.getItem('observatory-last-good')))}catch{}if(cached){transport='cache';install(cached)}else try{transport='fallback';install(await fetchJSON('/snapshot.json'))}catch{$('sync-status').className='sync-status warning';$('sync-status').textContent='数据暂时无法读取。请稍后刷新，或通过 GitHub 原始快照查看；此处不会用零替代未知。'}}}finally{requestBusy=false;$('refresh').disabled=false}}
function view(){const key=['overview','releases','feedback'].includes(location.hash.slice(1))?location.hash.slice(1):'overview';const names={overview:'总览',releases:'发布档案',feedback:'反馈与跟进'};document.querySelectorAll('[data-view]').forEach(a=>a.dataset.view===key?a.setAttribute('aria-current','page'):a.removeAttribute('aria-current'));for(const k of Object.keys(names))$(k+'-view').hidden=k!==key;$('breadcrumb').textContent=names[key];$('page-title').innerHTML=key==='overview'?'让每一次发布，<br class="mobile-break">都有下文。':key==='releases'?'发布不是数量，<br class="mobile-break">而是解决了什么。':'认真听见，<br class="mobile-break">也认真回应。';$('page-description').textContent={overview:'从解决一个问题，到听见真实反馈。这里记录完整的过程。',releases:'保留每次交付的问题阐释、验收证据与真实发布链接。',feedback:'把评论变成行动，把行动留成记录。'}[key]}
$('today').textContent=new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'long',day:'numeric',weekday:'long'}).format(new Date());$('refresh').addEventListener('click',refresh);$('search').addEventListener('input',render);$('project').addEventListener('change',()=>{if($('project').value!=='all')$('chart-project').value=$('project').value;render()});$('chart-project').addEventListener('change',renderChart);$('feedback-filter').addEventListener('change',render);for(const id of ['sources-button','footer-sources'])$(id).addEventListener('click',()=>$('source-dialog').showModal());$('close-dialog').addEventListener('click',()=>$('source-dialog').close());$('export').addEventListener('click',()=>{if(!data)return;const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='observatory-'+data.generated_at.slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});window.addEventListener('hashchange',view);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh()});setInterval(()=>{if(!document.hidden)refresh()},60000);view();refresh();
